class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: empty env vars return null on Linux.
        // Use HasEnvironmentVariable or a sentinel to distinguish unset from empty.
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val == null && !HasEnvironmentVariable("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    // Checks /proc/self/environ to detect vars that exist but are empty.
    static bool HasEnvironmentVariable(string name)
    {
        var environ = Environment.GetEnvironmentVariables();
        return environ.Contains(name);
    }
}

